def flatten_sort_unique(lst):
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result
    flat = flatten(lst)
    if len(flat) <= 1:
        return flat
    pivot = flat[len(flat)//2]
    left = [x for x in flat if x < pivot]
    mid = [x for x in flat if x == pivot]
    right = [x for x in flat if x > pivot]
    return flatten_sort_unique(left) + mid + flatten_sort_unique(right)

