def retry_flatten(func, max_attempts=3, delay=1):
    import time
    def attempt_flatten():
        result = func()
        if isinstance(result, list):
            flat = []
            for item in result:
                if isinstance(item, list):
                    flat.extend(retry_flatten(lambda: item, max_attempts, delay))
                else:
                    flat.append(item)
            return flat
        return result
