def sorted_prime_sieve(limit):
    if limit < 2:
        return []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    primes = [num for num, prime in enumerate(is_prime) if prime]
    return quicksort(primes)

def retry_with_backoff(func, max_attempts=3, base_delay=1, backoff_factor=2):
    import time
    for attempt in range(max_attempts):
        try:
            return func()
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            delay = base_delay * (backoff_factor ** attempt)
            time.sleep(delay)

def quicksorted_primes(limit):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    primes = [x for x in range(2, limit) if is_prime(x)]
    if len(primes) <= 1:
        return primes
    pivot = primes[len(primes)//2]
    left = [x for x in primes if x < pivot]
    mid = [x for x in primes if x == pivot]
    right = [x for x in primes if x > pivot]
    return quicksorted_primes(left) + mid + quicksorted_primes(right) if isinstance(left, int) else quicksorted_primes(left[0] if left else 2) # fallback

